[Form]
public class GUPPriceDiscPricingRulePreview extends FormRun
{
    private GUPPricingRule pricingRule;
    private GUPPricingRule pricingRuleCustHeader;
    private boolean        previewBothHeaderAndLine;
    private boolean        showHeaderPreview;
    private boolean        showLinePreview;

    private Query productPreviewQuery;
    private Query custPreviewQuery;

}

/// <summary>
/// Initialize form state and variables
/// </summary>
public void init()
{
    if (!element.args().record() || element.args().dataset() != tableNum(PriceDiscAdmTrans))
    {
        throw Error(Error::wrongUseOfFunction(funcName()));
    }

    PriceDiscAdmTrans priceDiscAdmTrans = element.args().record();
    GUPPriceComponentCodePriceAttributeGroupCombination combination = GUPPriceComponentCodePriceAttributeGroupCombination::find(priceDiscAdmTrans.PriceComponentCombination);
    showHeaderPreview = (combination.HeaderGroupAll == GUPGroupAll::Group);
    showLinePreview = (combination.LineGroupAll == GUPGroupAll::Group);

    switch (element.args().menuItemName())
    {
        case menuItemDisplayStr(GUPPriceDiscPricingRulePreview):
            pricingRule = GUPPricingRule::find(priceDiscAdmTrans.PricingRuleHeader);
            break;

        case menuItemDisplayStr(GUPPriceDiscPricingRulePreviewLine):
            pricingRule = GUPPricingRule::find(priceDiscAdmTrans.PricingRuleLine);
            break;

        case menuItemDisplayStr(GUPPriceDiscPricingRulePreviewAll):
            pricingRuleCustHeader = GUPPricingRule::find(priceDiscAdmTrans.PricingRuleHeader);
            pricingRule = GUPPricingRule::find(priceDiscAdmTrans.PricingRuleLine);
            previewBothHeaderAndLine = true;
            break;

        default: throw Error(Error::wrongUseOfFunction(funcName()));
    }

    element.researchPreviewQuery();

    super();

    element.setControlsVisible();

    AllVariantsBtn.text(pricingRule.ExclusionType == GUPPricingRuleExclusionType::Product
                                ? "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_AllVariants"
                                : "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_ProductMaster");
}

/// <summary>
/// Link line type table to Customer/Item/Product variant data source
/// </summary>
/// <param name = "_qbdsParent">Parent Customer/Item/Product data source</param>
private void addLineTypeLink(QueryBuildDataSource _qbdsParent)
{
    QueryBuildDataSource qbdsLineState = _qbdsParent.addDataSource(tableNum(GUPPricingAttributeLineState));
    qbdsLineState.relations(true);
    qbdsLineState.joinMode(JoinMode::OuterJoin);

    qbdsLineState.addRange(fieldNum(GUPPricingAttributeLineState, ParentTableId)).value(queryValue(pricingRule.TableId));
    qbdsLineState.addRange(fieldNum(GUPPricingAttributeLineState, ParentRecId)).value(queryValue(pricingRule.RecId));

    if (previewBothHeaderAndLine)
    {
        qbdsLineState.addRange(fieldNum(GUPPricingAttributeLineState, ParentRecId)).value(queryValue(pricingRuleCustHeader.RecId));
    }
}

/// <summary>
/// Expand product variants
/// </summary>
/// <param name = "_qbdsParent">Parent data source</param>
/// <param name = "_joinMode">Join mode</param>
public void addAllProductVariants(QueryBuildDataSource _qbdsParent, JoinMode _joinMode = JoinMode::InnerJoin)
{
    QueryBuildDataSource qbdsInventDimCombination = _qbdsParent.addDataSource(tableNum(InventDimCombination));

    qbdsInventDimCombination.addLink(fieldNum(InventTable, ItemId), fieldNum(InventDimCombination, ItemId));
    qbdsInventDimCombination.joinMode(_joinMode);
}

/// <summary>
/// Set controls visible depending on source level
/// </summary>
public void setControlsVisible()
{
    switch (pricingRule.getSourceLevel())
    {
        case GUPPricingAttributeSourceLevel::Header:
            PreviewCustTabPage.visible(true);
            PreviewProductTabPage.visible(false);
            break;

        case GUPPricingAttributeSourceLevel::Line:
            PreviewCustTabPage.visible(false);
            PreviewProductTabPage.visible(true);

            InventDimCombination_DistinctProductVariant.visible(pricingRule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant ? true : false);
            break;
    }

    if (previewBothHeaderAndLine)
    {
        PreviewCustTabPage.visible(true);
        PreviewProductTabPage.visible(true);
        InclExclCustBtn.visible(false);
        InclExclProductBtn.visible(false);
        AllVariantsBtn.visible(false);

        InventDimCombination_DistinctProductVariant.visible(pricingRule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant ? true : false);
    }

    if (!showHeaderPreview)
    {
        PreviewCustTabPage.visible(false);
    }

    if (!showLinePreview)
    {
        PreviewProductTabPage.visible(false);
    }
}

/// <summary>
/// Filter preview query according to slected pricing attributes
/// </summary>
private void researchPreviewQuery()
{
    switch (pricingRule.getSourceLevel())
    {
        case GUPPricingAttributeSourceLevel::Header:
            if (showHeaderPreview)
            {
                custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(pricingRule).build();
                element.addLineTypeLink(custPreviewQuery.dataSourceTable(tableNum(CustTable)));
            }
            break;

        case GUPPricingAttributeSourceLevel::Line:
            if (showLinePreview)
            {
                if (pricingRule.ExclusionType == GUPPricingRuleExclusionType::Product)
                {
                    productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(pricingRule).build();

                    element.addAllProductVariants(productPreviewQuery.dataSourceTable(tableNum(InventTable)), JoinMode::OuterJoin);
                    element.addLineTypeLink(productPreviewQuery.dataSourceTable(tableNum(InventTable)));
                }
                else
                {
                    productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(pricingRule, 0, '', true)
                                                                                                .addProductVariants()
                                                                                                .build();

                    element.addLineTypeLink(productPreviewQuery.dataSourceTable(tableNum(InventDimCombination)));
                }

                if (previewBothHeaderAndLine && pricingRuleCustHeader.RecId)
                {
                    custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(pricingRuleCustHeader).build();
                    element.addLineTypeLink(custPreviewQuery.dataSourceTable(tableNum(CustTable)));
                }
            }
            break;
    }
}

/// <summary>
/// Execute query for customer data source
/// </summary>
public void executeQuery()
{
    if (custPreviewQuery)
    {
        this.query(custPreviewQuery);
    }

    super();
}

public int active()
{
    int ret;

    ret = super();

    InclExclCustBtn.text(GUPPricingAttributeLineStateCust ? "@SYS28109" : "@SYS23992");

    return ret;
}

/// <summary>
/// Execute query for product data source
/// </summary>
public void executeQuery()
{
    if (productPreviewQuery)
    {
        this.query(productPreviewQuery);
    }

    InventDimCombination_ds.queryBuildDataSource().enabled(pricingRule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant);

    super();
}

public int active()
{
    int ret;

    ret = super();

    if (pricingRule.ExclusionType == GUPPricingRuleExclusionType::Product)
    {
        InclExclProductBtn.text(GUPPricingAttributeLineStateProduct ? "@SYS28109" : "@SYS23992");
    }

    return ret;
}

public int active()
{
    int ret;

    ret = super();

    InclExclProductBtn.text(GUPPricingAttributeLineStateProduct ? "@SYS28109" : "@SYS23992");

    return ret;
}

/// <summary>
/// Exclude record from pricing query
/// </summary>
public void clicked()
{
    GUPPricingAttributeLineType exclType = GUPPricingAttributeLineStateCust ? GUPPricingAttributeLineType::Include : GUPPricingAttributeLineType::Exclude;
    CustTable custTableLocal;

    super();

    for(custTableLocal = CustTable_ds.getFirst(true) ? CustTable_ds.getFirst(true) : CustTable_ds.cursor(); 
        custTableLocal; 
        custTableLocal = CustTable_ds.getNext())
    {
        pricingRule.inclExclRelLine(exclType, custTableLocal.TableId, custTableLocal.RecId);
    }

    CustTable_ds.research(true);
    CustTable_ds.refresh();
}

/// <summary>
/// Exclude record from pricing query
/// </summary>
public void clicked()
{            
    super();

    GUPPricingAttributeLineType exclType = GUPPricingAttributeLineStateProduct ? GUPPricingAttributeLineType::Include : GUPPricingAttributeLineType::Exclude;

    if (pricingRule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant)
    {                
        InventDimCombination inventDimCombinationLocal;

        for (   inventDimCombinationLocal = InventDimCombination_ds.getFirst(true) ? InventDimCombination_ds.getFirst(true) : InventDimCombination_ds.cursor();
                inventDimCombinationLocal;
                inventDimCombinationLocal = InventDimCombination_ds.getNext())
        {
            pricingRule.inclExclRelLine(exclType, inventDimCombinationLocal.TableId, inventDimCombinationLocal.RecId);
        }
    }
    else
    {
        InventTable inventTableLocal;

        for (   inventTableLocal = InventTable_ds.getFirst(true) ? InventTable_ds.getFirst(true) : InventTable_ds.cursor();
                inventTableLocal;
                inventTableLocal = InventTable_ds.getNext())
        {
            pricingRule.inclExclRelLine(exclType, inventTableLocal.TableId, inventTableLocal.RecId);
        }
    }

    InventTable_ds.research(true);
    InventTable_ds.refresh();
}

/// <summary>
/// Expand product variants
/// </summary>
public void clicked()
{
    super();

    ttsbegin;
    pricingRule.selectForUpdate(true);
    pricingRule.ExclusionType = pricingRule.ExclusionType == GUPPricingRuleExclusionType::Product 
                                    ? GUPPricingRuleExclusionType::ProductVariant
                                    : GUPPricingRuleExclusionType::Product;
    pricingRule.write();
    ttscommit;

    GUPPricingAttributeLineState::clearLineState(pricingRule.TableId, pricingRule.RecId);

    AllVariantsBtn.text(pricingRule.ExclusionType == GUPPricingRuleExclusionType::Product 
                            ? "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_AllVariants" 
                            : "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_ProductMaster");

    InventDimCombination_DistinctProductVariant.visible(pricingRule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant);

    element.researchPreviewQuery();
    InventTable_ds.executeQuery();
}
